{
 "app_name": "venmo",
 "api_name": "approve_payment_request",
 "path": "/payment_requests/{payment_request_id}/approve",
 "method": "POST",
 "description": "Approve a payment request.",
 "parameters": [
  {
   "name": "payment_request_id",
   "type": "integer",
   "required": true,
   "description": "ID of the payment request to approve.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "payment_card_id",
   "type": "integer",
   "required": false,
   "description": "ID of the payment card to use for approving the payment request. If not passed, Venmo balance will be used.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}

